// Some portions generated by Codex
import assert from "node:assert/strict";
import test from "node:test";
import { facetModel, valuesInRange } from "../../../main/frontend/graph-explorer/graph-facets.ts";
import { rangeSparqlFilter } from "../../../main/frontend/graph-explorer/facet-queries.ts";

const XSD = "http://www.w3.org/2001/XMLSchema#";
function range(values) {
  const resources = values.map((_, index) => ({ id: `urn:source:${index}`, kind: "iri", label: `Source ${index}` }));
  const literals = values.map(({ value, datatype, language }, index) => ({ id: `literal:${index}`, kind: "literal", label: value, termValue: value, datatype, language }));
  const model = facetModel({ nodes: resources, edges: resources.map((node, index) => ({ id: `edge:${index}`, source: node.id, predicate: "urn:p", label: "Property", target: literals[index].id })), nodeById: new Map([...resources, ...literals].map(node => [node.id, node])), selection: new Map(), typesOf: () => [], hiddenPredicates: new Set() });
  return model.facets.find(({ id }) => id === "urn:p");
}

test("numeric lexical ranges retain signed, exponent, whitespace, language and custom datatype literals", () => {
  const facet = range([
    { value: " +2.5 ", datatype: `${XSD}string` },
    { value: "3e0", datatype: `${XSD}double` },
    { value: "-2", datatype: "urn:custom" },
    { value: ".5", language: "en" },
  ]);
  assert.equal(facet.range.kind, "number");
  assert.deepEqual(valuesInRange(facet, "0.5", "3"), new Set(["literal:0", "literal:1", "literal:3"]));
  assert.deepEqual(valuesInRange(facet, "0x2", "3"), new Set(["literal:0", "literal:1", "literal:2", "literal:3"]), "invalid numeric bounds are ignored consistently by the UI and query");
  for (const invalid of ["", "NaN", "INF", "0x2", "2oops", "1e999"]) {
    assert.equal(range([{ value: invalid }, { value: "1" }, { value: "2" }, { value: "3" }]).range, undefined, invalid);
  }
});

test("date ranges use calendar days including a dateTime with a timezone crossing UTC midnight", () => {
  const facet = range([
    { value: "2024", datatype: `${XSD}gYear` },
    { value: "2024-01", datatype: `${XSD}gYearMonth` },
    { value: "2024-01-01", datatype: `${XSD}date` },
    { value: "2024-01-01T23:00:00-05:00", datatype: `${XSD}dateTime` },
  ]);
  assert.equal(facet.range.kind, "date");
  assert.deepEqual(valuesInRange(facet, "2024-01-01", "2024-01-01"), new Set(["literal:0", "literal:1", "literal:2", "literal:3"]));
  assert.equal(range([{ value: "2024-02-30" }, { value: "2024-02-01" }, { value: "2024-02-02" }, { value: "2024-02-03" }]).range, undefined);
});

test("empty range bounds produce no filter while invalid bounds cannot become SPARQL code", () => {
  assert.equal(rangeSparqlFilter("?value", { kind: "number", from: "", to: "" }), null);
  const invalid = rangeSparqlFilter("?value", { kind: "number", from: '0) || true || (0', to: "1e999" });
  assert.doesNotMatch(invalid ?? "", /true \|\|/);
});
